"""Re-emit a valid image with different (but legal) physical placement choices."""
import random, sys
sys.path.insert(0, '/workspace/tmp/dev')
import ref
from imgtool import gf, sf

BMP_NULL = 4194303

def parse_tree(img):
    rows = [[int(w, 16) for w in b] for b in img['banks']]
    cells = img['cells']
    bitmaps = [int(b, 16) for b in img['bitmaps']]
    nexthops = list(img['nexthops'])
    nodes = []
    index = {}
    roots = []
    queue = []
    if img['root'] is not None:
        queue.append((img['root'][0], img['root'][1], False, 0, 0, 0, ('root', None)))
    for i, e in enumerate(img['front16']):
        queue.append((e[1], e[2], False, 16, 16, int(e[0], 16) << 112, ('f16', i)))
    for i, e in enumerate(img['front64']):
        queue.append((e[1], e[2], False, 64, 64, int(e[0], 16) << 64, ('f64', i)))
    while queue:
        s, c, bulk, origin, depth, region, tag = queue.pop(0)
        assert (s, c) not in index, 'node visited twice'
        base = 128 if (c & 1) else 0
        row = rows[s][c // 2]
        t = gf(row, base, 3)
        idx = len(nodes)
        index[(s, c)] = idx
        n = dict(idx=idx, origin=origin, depth=depth, region=region, type=t, tag=tag,
                 bmp=gf(row, base + 3, 22), kids=[], inl=[], hops=[], pattern=0, level=(depth - origin) // 6)
        nodes.append(n)
        if t <= 3:
            pat = bitmaps[gf(row, base + 25, 16)]
            nb = gf(row, base + 41, 22)
            n['pattern'] = pat
            off = 0
            for p in range(1, 64):
                if (pat >> p) & 1:
                    n['hops'].append(nexthops[nb + off]); off += 1
            nslots = {1: 2, 2: 6, 3: 3}[t]
            cbase = {1: 63, 2: 63, 3: 153}[t]
            for i in range(nslots):
                v = gf(row, base + cbase + 32 * i, 32)
                if ((v >> 6) & 15) == 15: continue
                n['kids'].append([v & 63, (v >> 6) & 15, v >> 10, None])
            if t == 3:
                bm = gf(row, base + 63, 64); bb = gf(row, base + 127, 22); bs = gf(row, base + 149, 4)
                i = 0
                for k in range(64):
                    if (bm >> k) & 1:
                        n['kids'].append([k, bs, bb + 2 * i, None]); i += 1
        else:
            for i in range(1 if t == 4 else 2):
                pos = base + (25 if i == 0 else 119)
                n['inl'].append([gf(row, pos, 64), gf(row, pos + 64, 8), gf(row, pos + 72, 22)])
        for kid in n['kids']:
            queue.append((kid[1], kid[2], False, origin, depth + 6,
                          region | (kid[0] << (128 - depth - 6)), None))
    # second pass: resolve child node indices
    for n in nodes:
        for kid in n['kids']:
            kid[3] = index[(kid[1], kid[2])]
        n['kids'].sort(key=lambda k: k[0])
    return nodes

def repack(img, rng=None, stage_seed=None, direct_mode='random', bulk_first=False,
           ni_shuffle=True, swap5=True):
    rng = rng or random.Random(0)
    nodes = parse_tree(img)
    maxlevel = max([n['level'] for n in nodes] + [0])
    # random strictly decreasing stage per level
    pool = list(range(11))
    rng.shuffle(pool)
    stages = sorted(pool[:maxlevel + 1], reverse=True)
    for n in nodes:
        n['stage'] = stages[n['level']]
    # direct / bulk choice for TYPE3
    for n in nodes:
        n['is_bulk'] = False
    for n in nodes:
        if n['type'] != 3: continue
        c = len(n['kids'])
        dmax = min(3, c - 4)
        if direct_mode == 'max': d = dmax
        elif direct_mode == 'min': d = 0
        else: d = rng.randint(0, dmax)
        pick = rng.sample(range(c), d)
        n['direct'] = set(pick)
        bm = 0
        for i, kid in enumerate(n['kids']):
            if i in n['direct']:
                kid[4] = False
            else:
                kid[4] = True
                bm |= 1 << kid[0]
                nodes[kid[3]]['is_bulk'] = True
        n['bulk_bm'] = bm
    # allocation per stage
    cells = [0] * 11
    units = {s: [] for s in range(11)}          # even blocks
    singles = {s: [] for s in range(11)}        # 1-cell units
    bulkgroups = {s: [] for s in range(11)}
    for n in nodes:
        if n['type'] == 3:
            bulkgroups[n['stage'] - 1 if False else stages[n['level'] + 1]].append(n)
    for n in nodes:
        if n['is_bulk']: continue
        size = {1: 1, 2: 2, 3: 2, 4: 1, 5: 2}[n['type']]
        if size == 2: units[n['stage']].append(n)
        else: singles[n['stage']].append(n)
    for s in range(11):
        rng.shuffle(units[s]); rng.shuffle(singles[s]); rng.shuffle(bulkgroups[s])
        blocks = []
        for n in units[s]: blocks.append(('node', n))
        for g in bulkgroups[s]: blocks.append(('bulk', g))
        sp = list(singles[s])
        pairs = []
        while len(sp) >= 2:
            pairs.append((sp.pop(), sp.pop()))
        for p in pairs: blocks.append(('pair', p))
        rng.shuffle(blocks)
        cur = 0
        for kind, obj in blocks:
            if kind == 'node':
                obj['cell'] = cur; cur += 2
            elif kind == 'pair':
                obj[0]['cell'] = cur; obj[1]['cell'] = cur + 1; cur += 2
            else:
                obj['bulk_base'] = cur
                i = 0
                for kid in obj['kids']:
                    if not kid[4]: continue
                    nodes[kid[3]]['cell'] = cur + 2 * i
                    nodes[kid[3]]['stage'] = s
                    i += 1
                cur += 2 * i
        if sp:
            sp[0]['cell'] = cur; cur += 1
        cells[s] = cur
    # NI array
    order = list(nodes)
    if ni_shuffle: rng.shuffle(order)
    ni = []
    for n in order:
        if n['type'] > 3: continue
        if not n['hops']:
            n['ni_base'] = 0
        else:
            n['ni_base'] = len(ni)
            ni.extend(n['hops'])
    pats = sorted({n['pattern'] for n in nodes if n['type'] <= 3})
    bid = {p: i for i, p in enumerate(pats)}
    if swap5:
        for n in nodes:
            if n['type'] == 5 and len(n['inl']) == 2 and rng.random() < 0.5:
                n['inl'].reverse()
    # emit
    banks = [[0] * ((cells[s] + 1) // 2) for s in range(11)]
    def putrow(s, cell):
        return (banks[s][cell // 2], 128 if (cell & 1) else 0)
    for n in nodes:
        row, base = putrow(n['stage'], n['cell'])
        pos = base
        def w(v, bits):
            nonlocal row, pos
            row = sf(row, pos, bits, v); pos += bits
        w(n['type'], 3); w(n['bmp'], 22)
        if n['type'] <= 3:
            w(bid[n['pattern']], 16); w(n['ni_base'], 22)
        if n['type'] in (1, 2):
            slots = 2 if n['type'] == 1 else 6
            for i in range(slots):
                if i < len(n['kids']):
                    k = n['kids'][i]
                    ch = nodes[k[3]]
                    w(k[0] | (ch['stage'] << 6) | (ch['cell'] << 10), 32)
                else:
                    w(15 << 6, 32)
        elif n['type'] == 3:
            w(n['bulk_bm'], 64); w(n['bulk_base'], 22); w(stages[n['level'] + 1], 4)
            direct = [k for i, k in enumerate(n['kids']) if i in n['direct']]
            for i in range(3):
                if i < len(direct):
                    k = direct[i]; ch = nodes[k[3]]
                    w(k[0] | (ch['stage'] << 6) | (ch['cell'] << 10), 32)
                else:
                    w(15 << 6, 32)
        elif n['type'] in (4, 5):
            for frag, l8, hop in n['inl']:
                w(frag, 64); w(l8, 8); w(hop, 22)
        banks[n['stage']][n['cell'] // 2] = row
        if n['is_bulk'] and n['type'] in (1, 4):
            # upper half stays zero padding
            assert gf(banks[n['stage']][n['cell'] // 2], 128, 128) == 0
    out = dict(root=None, front16=[], front64=[], cells=cells,
               banks=[['%064x' % w for w in b] for b in banks],
               bitmaps=['%016x' % p for p in pats], nexthops=ni)
    for n in nodes:
        if n['tag'] is None: continue
        kind, i = n['tag']
        loc = [n['stage'], n['cell']]
        if kind == 'root': out['root'] = loc
        elif kind == 'f16': out['front16'].append([img['front16'][i][0], loc[0], loc[1]])
        else: out['front64'].append([img['front64'][i][0], loc[0], loc[1]])
    out['front16'].sort(key=lambda e: int(e[0], 16))
    out['front64'].sort(key=lambda e: int(e[0], 16))
    return out
