import json, random, sys
sys.path.insert(0, '/workspace/tmp/dev')
from harness import *
import repack, ref

rng = random.Random(3)
base = json.load(open('/workspace/tmp/dev/base_img.json'))
ok, reason, fib0 = ref.validate_image(base, want_fib=True)
assert ok, reason
addrs = [a for (a, l, h) in fib0] + [0, (1 << 128) - 1] + [rng.getrandbits(128) for _ in range(20)]
exp = [ref.lpm(fib0, a) for a in addrs]

def one(name, img):
    ok, reason = ref.validate_image(img)
    ops = [['load', img], ['image_query', [hx(a) for a in addrs]]]
    resp = run({'cases': [{'ops': ops}]})
    r = resp['results'][0]
    good = r['loads'] == [True] and r['answers'] == exp
    print(('OK  ' if (good and ok) else 'BAD ') + name, 'py=%s %s cpp_load=%s answers_ok=%s'
          % (ok, reason, r['loads'], r['answers'] == exp))
    return good and ok

fails = 0
for i in range(6):
    r2 = random.Random(100 + i)
    img = repack.repack(base, rng=r2)
    if not one('repack random #%d' % i, img): fails += 1
for mode in ('max', 'min'):
    img = repack.repack(base, rng=random.Random(9), direct_mode=mode)
    if not one('repack direct=%s' % mode, img): fails += 1
img = repack.repack(base, rng=random.Random(11), ni_shuffle=False, swap5=False)
if not one('repack canonical order', img): fails += 1
print('FAILS', fails)
